//! Material You color themes, as generated by [matugen](https://github.com/InioX/matugen).
//!
//! matugen derives a Material 3 color scheme from a wallpaper or a seed color. A
//! [`Theme`] holds one such scheme: every Material 3 color role, in the mode (dark or
//! light) it was generated for. It reads matugen's JSON in any of the forms matugen
//! writes:
//!
//! - the `--json` dump of matugen 4 (`"primary": {"dark": {"color": ..}, "default": ..}`),
//! - the dump of earlier versions, or `--old-json-output` (`"primary": {"dark": "#.."}`),
//! - a flat `"primary": "#.."` map, as rendered by a matugen template,
//!
//! with colors in any `--json` format (`hex`, `strip`, `rgb`, `rgba`, `hsl`, `hsla`).
//!
//! ```sh
//! matugen image wallpaper.png --json hex > ~/.config/shell/theme.json
//! ```

mod watch;

use std::{collections::HashMap, error::Error, fmt, fs, path::Path, sync::OnceLock};

use serde_json::{Map, Value};
use shell_render::Color;
use shell_ui::Frame;

pub use watch::watch_theme;

/// The [`Theme`] a view is built with: the one [provided](shell_ui::Ui::provide) to the UI (by
/// [`watch_theme`], say), or [`Theme::default`]. It lives as long as the frame, so it can
/// be held while the frame animates.
pub trait ThemeExt<'a> {
    fn theme(&self) -> &'a Theme;
}

impl<'a> ThemeExt<'a> for Frame<'a> {
    fn theme(&self) -> &'a Theme {
        self.get().unwrap_or_else(|| Theme::fallback())
    }
}

/// Whether a scheme is meant for dark or light surroundings.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum ThemeMode {
    #[default]
    Dark,
    Light,
}

impl ThemeMode {
    fn key(self) -> &'static str {
        match self {
            Self::Dark => "dark",
            Self::Light => "light",
        }
    }
}

/// Declares [`Theme`]'s role fields and the matching JSON keys from one list.
macro_rules! roles {
    ($($(#[$doc:meta])* $role:ident,)*) => {
        /// A Material 3 color scheme. See the [roles](https://m3.material.io/styles/color/roles)
        /// for what each color is for; `on_*` colors are for content drawn on top of the
        /// color of the same name.
        ///
        /// ```ignore
        /// let theme = ui.theme();
        /// Element::text("12:34")
        ///     .text_color(theme.on_primary_container)
        ///     .background(theme.primary_container)
        /// ```
        #[derive(Clone, Debug, PartialEq)]
        pub struct Theme {
            pub mode: ThemeMode,
            $($(#[$doc])* pub $role: Color,)*
        }

        /// The key of every role in matugen's output.
        const ROLES: &[&str] = &[$(stringify!($role)),*];

        impl Theme {
            fn from_roles(mode: ThemeMode, colors: &HashMap<&str, Color>) -> Self {
                Self { mode, $($role: colors[stringify!($role)],)* }
            }
        }
    };
}

roles! {
    /// The seed color the scheme was generated from.
    source_color,

    /// Prominent components: active indicators, key buttons.
    primary,
    on_primary,
    /// Less prominent fills in the primary hue: selected items, chips.
    primary_container,
    on_primary_container,
    primary_fixed,
    primary_fixed_dim,
    on_primary_fixed,
    on_primary_fixed_variant,
    inverse_primary,

    secondary,
    on_secondary,
    secondary_container,
    on_secondary_container,
    secondary_fixed,
    secondary_fixed_dim,
    on_secondary_fixed,
    on_secondary_fixed_variant,

    /// Contrasting accents.
    tertiary,
    on_tertiary,
    tertiary_container,
    on_tertiary_container,
    tertiary_fixed,
    tertiary_fixed_dim,
    on_tertiary_fixed,
    on_tertiary_fixed_variant,

    error,
    on_error,
    error_container,
    on_error_container,

    background,
    on_background,
    /// The default fill for large areas such as bars and panels.
    surface,
    /// The default color for text and icons.
    on_surface,
    surface_variant,
    /// Lower-emphasis text and icons.
    on_surface_variant,
    surface_dim,
    surface_bright,
    surface_tint,
    /// Surface fills at increasing elevation, for nesting containers.
    surface_container_lowest,
    surface_container_low,
    surface_container,
    surface_container_high,
    surface_container_highest,
    inverse_surface,
    inverse_on_surface,

    /// Borders and dividers.
    outline,
    /// Subtle dividers.
    outline_variant,
    shadow,
    scrim,
}

impl Theme {
    /// Parses matugen's JSON output (see the [module docs](self) for the forms accepted).
    /// Colors are taken from the mode matugen generated for (`--mode`, dark by default).
    pub fn from_matugen_json(source: &str) -> Result<Self, ThemeError> {
        let root: Value = serde_json::from_str(source).map_err(ThemeError::Json)?;
        let mode = match (root.get("mode").and_then(Value::as_str), root.get("is_dark_mode")) {
            (Some("light"), _) | (None, Some(Value::Bool(false))) => ThemeMode::Light,
            _ => ThemeMode::Dark,
        };
        let colors = root.get("colors").and_then(Value::as_object).ok_or(ThemeError::NoColors)?;
        // Very old versions grouped colors by mode rather than by role.
        let colors = match colors.get(mode.key()) {
            Some(Value::Object(by_mode)) if !colors.contains_key("primary") => by_mode,
            _ => colors,
        };

        let mut found = HashMap::new();
        let mut missing = Vec::new();
        for &role in ROLES {
            match role_value(colors, role, mode) {
                None => missing.push(role.to_owned()),
                Some(text) => {
                    let color = parse_color(text).ok_or_else(|| ThemeError::InvalidColor {
                        role: role.to_owned(),
                        value: text.to_owned(),
                    })?;
                    found.insert(role, color);
                }
            }
        }
        if !missing.is_empty() {
            return Err(ThemeError::MissingRoles(missing));
        }
        Ok(Self::from_roles(mode, &found))
    }

    /// Reads and parses a file of matugen output.
    pub fn load(path: impl AsRef<Path>) -> Result<Self, ThemeError> {
        let source = fs::read_to_string(path).map_err(ThemeError::Io)?;
        Self::from_matugen_json(&source)
    }
}

impl Theme {
    fn fallback() -> &'static Self {
        static DEFAULT: OnceLock<Theme> = OnceLock::new();
        DEFAULT.get_or_init(Theme::default)
    }
}

impl Default for Theme {
    /// A dark scheme generated by matugen from the seed color `#6b8f71`, a sage green.
    fn default() -> Self {
        Self::from_matugen_json(include_str!("default.json")).expect("bundled theme is valid")
    }
}

/// The color string for `role`, whichever of matugen's layouts it is in.
fn role_value<'a>(colors: &'a Map<String, Value>, role: &str, mode: ThemeMode) -> Option<&'a str> {
    let value = match colors.get(role)? {
        // Per-mode variants; `default` is the mode that was generated.
        Value::Object(variants) if !variants.contains_key("color") => {
            variants.get("default").or_else(|| variants.get(mode.key()))?
        }
        value => value,
    };
    match value {
        Value::String(text) => Some(text),
        Value::Object(object) => object.get("color")?.as_str(),
        _ => None,
    }
}

/// Any color format matugen's `--json` option produces: `#rrggbb`, `rrggbb`,
/// `rgb(r, g, b)`, `rgba(r, g, b, a)`, `hsl(h, s%, l%)` and `hsla(h, s%, l%, a)`.
/// Hex may also carry an alpha byte (`#rrggbbaa`).
fn parse_color(text: &str) -> Option<Color> {
    let text = text.trim();
    if let Some((function, args)) = text.strip_suffix(')').and_then(|t| t.split_once('(')) {
        let args: Vec<&str> = args.split(',').map(str::trim).collect();
        let number = |i: usize| args.get(i)?.trim_end_matches('%').parse::<f32>().ok();
        let alpha = |i: usize| if args.len() > i { number(i) } else { Some(1.0) };
        return match (function.trim(), args.len()) {
            ("rgb", 3) | ("rgba", 4) => Some(Color::rgba(
                number(0)? / 255.0,
                number(1)? / 255.0,
                number(2)? / 255.0,
                alpha(3)?,
            )),
            ("hsl", 3) | ("hsla", 4) => {
                let [r, g, b] = hsl_to_rgb(number(0)?, number(1)? / 100.0, number(2)? / 100.0);
                Some(Color::rgba(r, g, b, alpha(3)?))
            }
            _ => None,
        };
    }

    let digits = text.strip_prefix('#').unwrap_or(text);
    if !digits.bytes().all(|b| b.is_ascii_hexdigit()) {
        return None;
    }
    let value = u32::from_str_radix(digits, 16).ok()?;
    match digits.len() {
        6 => Some(Color::hex(value)),
        8 => Some(Color::hex(value >> 8).with_alpha((value & 0xff) as f32 / 255.0)),
        _ => None,
    }
}

/// `hue` in degrees; `saturation` and `lightness` in `0..=1`.
fn hsl_to_rgb(hue: f32, saturation: f32, lightness: f32) -> [f32; 3] {
    let chroma = (1.0 - (2.0 * lightness - 1.0).abs()) * saturation;
    let h = hue.rem_euclid(360.0) / 60.0;
    let x = chroma * (1.0 - (h % 2.0 - 1.0).abs());
    let [r, g, b] = match h as u32 {
        0 => [chroma, x, 0.0],
        1 => [x, chroma, 0.0],
        2 => [0.0, chroma, x],
        3 => [0.0, x, chroma],
        4 => [x, 0.0, chroma],
        _ => [chroma, 0.0, x],
    };
    let m = lightness - chroma / 2.0;
    [r + m, g + m, b + m]
}

#[derive(Debug)]
pub enum ThemeError {
    Io(std::io::Error),
    Json(serde_json::Error),
    /// There is no `colors` object.
    NoColors,
    /// These roles were not found.
    MissingRoles(Vec<String>),
    /// A role's value isn't a color.
    InvalidColor {
        role: String,
        value: String,
    },
}

impl fmt::Display for ThemeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(e) => write!(f, "{e}"),
            Self::Json(e) => write!(f, "invalid JSON: {e}"),
            Self::NoColors => write!(f, "no \"colors\" object; is this matugen output?"),
            Self::MissingRoles(roles) => write!(f, "missing colors: {}", roles.join(", ")),
            Self::InvalidColor { role, value } => write!(f, "{role}: {value:?} is not a color"),
        }
    }
}

impl Error for ThemeError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io(e) => Some(e),
            Self::Json(e) => Some(e),
            _ => None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // Generated by matugen 4.2.0 from `color hex '#7cafc2'`, trimmed to mode and colors.
    const V4_HEX: &str = include_str!("testdata/v4-hex.json");
    const V3_HEX: &str = include_str!("testdata/v3-hex.json"); // --old-json-output
    const V4_RGBA: &str = include_str!("testdata/v4-rgba.json");
    const V4_HSL: &str = include_str!("testdata/v4-hsl.json");
    const V4_STRIP_LIGHT: &str = include_str!("testdata/v4-strip-light.json"); // -m light

    fn parse(source: &str) -> Theme {
        Theme::from_matugen_json(source).unwrap()
    }

    #[test]
    fn reads_every_json_layout_and_color_format() {
        let theme = parse(V4_HEX);
        assert_eq!(theme.mode, ThemeMode::Dark);
        assert_eq!(theme.primary, Color::hex(0x87d1eb));
        assert_eq!(theme.surface, Color::hex(0x0f1416));
        assert_eq!(parse(V3_HEX), theme);
        assert_eq!(parse(V4_RGBA), theme);
    }

    #[test]
    fn hsl_is_close_to_hex() {
        // matugen rounds HSL to whole units, so it can't round-trip exactly.
        let (hsl, hex) = (parse(V4_HSL), parse(V4_HEX));
        for (a, b) in [(hsl.primary, hex.primary), (hsl.on_surface, hex.on_surface)] {
            for (x, y) in [(a.r, b.r), (a.g, b.g), (a.b, b.b)] {
                assert!((x - y).abs() < 3.0 / 255.0, "{a:?} vs {b:?}");
            }
        }
    }

    #[test]
    fn takes_the_generated_mode() {
        let light = parse(V4_STRIP_LIGHT);
        assert_eq!(light.mode, ThemeMode::Light);
        assert_eq!(light.primary, Color::hex(0x05677e));
    }

    #[test]
    fn reads_flat_template_output() {
        let mut flat = Map::new();
        for &role in ROLES {
            flat.insert(role.into(), Value::String("#123456".into()));
        }
        let json = serde_json::json!({ "mode": "light", "colors": flat }).to_string();
        let theme = parse(&json);
        assert_eq!(theme.mode, ThemeMode::Light);
        assert_eq!(theme.scrim, Color::hex(0x123456));
    }

    #[test]
    fn reports_missing_and_invalid_colors() {
        let mut root: Value = serde_json::from_str(V4_HEX).unwrap();
        root["colors"].as_object_mut().unwrap().remove("scrim");
        assert!(matches!(
            Theme::from_matugen_json(&root.to_string()),
            Err(ThemeError::MissingRoles(roles)) if roles == ["scrim"]
        ));
        root["colors"]["scrim"] = Value::String("nope".into());
        assert!(matches!(
            Theme::from_matugen_json(&root.to_string()),
            Err(ThemeError::InvalidColor { role, .. }) if role == "scrim"
        ));
        assert!(matches!(Theme::from_matugen_json("{}"), Err(ThemeError::NoColors)));
    }

    #[test]
    fn parses_color_strings() {
        assert_eq!(parse_color("#ff8000"), Some(Color::hex(0xff8000)));
        assert_eq!(parse_color("ff8000"), Some(Color::hex(0xff8000)));
        assert_eq!(parse_color("#ff800080"), Some(Color::hex(0xff8000).with_alpha(128.0 / 255.0)));
        assert_eq!(parse_color("rgb(255, 128, 0)"), Some(Color::hex(0xff8000)));
        assert_eq!(
            parse_color("rgba(255, 128, 0, 0.5)"),
            Some(Color::hex(0xff8000).with_alpha(0.5))
        );
        assert_eq!(parse_color("hsl(0, 100%, 50%)"), Some(Color::rgb(1.0, 0.0, 0.0)));
        assert_eq!(parse_color("#ff80"), None);
        assert_eq!(parse_color("+12345"), None);
    }
}
